import React,{useEffect,useMemo,useState} from 'react';
import { createUniverse, RARITIES, rarityCounts } from './sim/generate.js';
import { OFFSEASON_STAGES, ensureUniverse, simulateWeeks, simulateToSeasonEnd, beginOffseason, advanceOffseasonStage, startNextSeason, getStandings, getRoster, findTeam, findPlayer, getTeamStrength, getAllCoaches } from './sim/season.js';
import { TeamMark,RarityPill,ProbabilityStrip,Metric,Panel,Segmented,Empty } from './components/ui.jsx';

const NAV=['Home','NFL','College','UFL','Players','Stats','Coaches','Market','Draft','Offseason','ESPN','Records','Universe'];
const money=n=>`$${Number(n||0).toFixed(1)}M`;
const num=n=>Number(n||0).toLocaleString();
const rr=r=>RARITIES.indexOf(r);
const cls=y=>['','FR','SO','JR','SR'][y]||'—';
const statLine=p=>{const s=p?.currentSeason||p?.stats?.seasons?.at(-1)||{};if(p.position==='QB')return`${num(s.passYards)} YDS · ${s.passTD||0} TD · ${s.interceptions||0} INT`;if(['HB','FB'].includes(p.position))return`${num(s.rushYards)} RUSH · ${s.rushTD||0} TD`;if(['WR','TE'].includes(p.position))return`${num(s.recYards)} REC YDS · ${s.recTD||0} TD`;return`${s.tackles||0} TKL · ${s.sacks||0} SCK · ${s.defInterceptions||0} INT`;};
const leagueName=l=>l==='COLLEGE'?'College Football':l;
const teamRecord=t=>`${t?.current?.wins||0}-${t?.current?.losses||0}`;

function SaveHub({universe,setUniverse}){const[seed,setSeed]=useState('Gridiron-1');const save=slot=>{localStorage.setItem(`afwc-save-${slot}`,JSON.stringify(universe));localStorage.setItem('afwc-active-slot',String(slot));};const load=slot=>{const raw=localStorage.getItem(`afwc-save-${slot}`);if(raw)setUniverse(ensureUniverse(JSON.parse(raw)));};const fresh=()=>setUniverse(createUniverse(seed||`Gridiron-${Date.now()}`));return <Panel title="Universe saves" eyebrow="LOCAL DYNASTY ARCHIVE" action={<button className="small-btn" onClick={fresh}>New universe</button>}><div className="save-row">{[1,2,3].map(slot=>{const raw=localStorage.getItem(`afwc-save-${slot}`);let label='Empty';if(raw){try{const x=JSON.parse(raw);label=`Year ${x.year} · ${x.seedText}`;}catch{}}return <div className="save-card" key={slot}><b>Slot {slot}</b><span>{label}</span><div><button onClick={()=>save(slot)}>Save</button><button disabled={!raw} onClick={()=>load(slot)}>Load</button></div></div>})}</div><div className="seed-row"><input value={seed} onChange={e=>setSeed(e.target.value)} placeholder="Universe seed"/><button onClick={fresh}>Generate from seed</button></div></Panel>}

function Header({u,run,simulating}){
  const week=u.seasonState?.week||0,stage=u.offseasonState?.stageIndex||0;
  return <header className="topbar"><div className="brand"><div className="brand-ball">W</div><div><strong>WORLD CHRONICLE</strong><span>AMERICAN FOOTBALL</span></div></div><div className="season-chip"><span>UNIVERSE</span><b>YEAR {u.year}</b><small>{u.phase==='Regular Season'?`Week ${week} / 18`:u.phase}</small></div><div className="sim-actions">{(u.phase==='Preseason'||u.phase==='Regular Season')&&<><button onClick={()=>run('week')} disabled={simulating}>+1 WEEK</button><button onClick={()=>run('four')} disabled={simulating}>+4 WEEKS</button><button className="advance" onClick={()=>run('end')} disabled={simulating}>TO SEASON END <span>›</span></button></>}{u.phase==='Season Complete'&&<button className="advance" onClick={()=>run('offseason')} disabled={simulating}>ADVANCE TO OFFSEASON <span>›</span></button>}{u.phase==='Offseason'&&<button className="advance" onClick={()=>run('stage')} disabled={simulating}>RUN {OFFSEASON_STAGES[stage]||'OFFSEASON'} <span>›</span></button>}{u.phase==='Ready for Next Season'&&<button className="advance" onClick={()=>run('next')} disabled={simulating}>START YEAR {u.year+1} <span>›</span></button>}</div></header>
}

function CompetitionWinner({u,league,summary,openTeam,openPlayer}){if(!summary)return null;const c=findTeam(u,summary.championId),r=findTeam(u,summary.runnerUpId),m=findPlayer(u,summary.awards?.mvpId);return <div className="winner-card"><div className="winner-top"><span>{leagueName(league)}</span><b>{summary.finalScore}</b></div><button onClick={()=>openTeam(c?.id)}><TeamMark team={c} size={42}/><span><small>CHAMPION · {summary.championRecord}</small><strong>{c?.name}</strong></span></button><div className="winner-meta"><span>Runner-up <b onClick={()=>r&&openTeam(r.id)}>{r?.name}</b></span><span>{league==='COLLEGE'?'Heisman':'MVP'} <b onClick={()=>m&&openPlayer(m.id)}>{m?.name}</b></span></div></div>}

function Home({u,openTeam,openPlayer,run}){
  const nfl=getStandings(u,'NFL'),college=getStandings(u,'COLLEGE'),latest=u.seasonHistory[0],seasonDone=u.phase==='Season Complete'||u.phase==='Offseason'||u.phase==='Ready for Next Season';
  const leaders=useMemo(()=>u.players.filter(p=>!p.retired&&p.currentSeason).sort((a,b)=>{const x=p=>(p.currentSeason?.passYards||0)+(p.currentSeason?.rushYards||0)+(p.currentSeason?.recYards||0);return x(b)-x(a)}).slice(0,5),[u]);
  if(seasonDone&&latest?.year===u.year)return <div className="page"><div className="season-finale"><div><div className="eyebrow">YEAR {u.year} COMPLETE</div><h1>The chapter is written.</h1><p>Champions, awards and records are locked. The offseason remains separate so you can watch the universe change one market phase at a time.</p></div>{u.phase==='Season Complete'&&<button className="advance giant" onClick={()=>run('offseason')}>ADVANCE TO OFFSEASON <span>›</span></button>}</div><div className="winner-grid"><CompetitionWinner u={u} league="NFL" summary={latest.NFL} openTeam={openTeam} openPlayer={openPlayer}/><CompetitionWinner u={u} league="COLLEGE" summary={latest.COLLEGE} openTeam={openTeam} openPlayer={openPlayer}/><CompetitionWinner u={u} league="UFL" summary={latest.UFL} openTeam={openTeam} openPlayer={openPlayer}/></div><AwardsSummary u={u} latest={latest} openPlayer={openPlayer}/><Panel title="Season headlines" eyebrow="ESPN · FINAL EDITION"><div className="news-stack">{u.news.filter(n=>n.year===u.year).slice(0,10).map(n=><button className="news-item" key={n.id} onClick={()=>n.playerId?openPlayer(n.playerId):n.teamId?openTeam(n.teamId):null}><span className={`news-type ${n.importance>=85?'hot':''}`}>{n.type}</span><div><b>{n.title}</b><p>{n.body}</p></div><time>Y{n.year}</time></button>)}</div></Panel></div>;
  return <div className="page"><div className="hero-grid"><div className="hero-copy"><div className="eyebrow">THE LIVING FOOTBALL UNIVERSE</div><h1>Year {u.year}. Week {u.seasonState?.week||0}.</h1><p>Advance one week, four weeks, or straight to the postseason. College talent is uncertain; professional careers become visible only after draft night.</p><div className="hero-stats"><Metric label="NFL leader" value={nfl[0]?.name||'—'} sub={teamRecord(nfl[0])}/><Metric label="College #1" value={college[0]?.name||'—'} sub={teamRecord(college[0])}/><Metric label="Games played" value={num(u.currentGames.length)}/><Metric label="Tracked players" value={num(u.players.filter(p=>!p.retired).length)}/></div></div><div className="hero-card"><div className="scorebug"><span>SIMULATION CONTROL</span><b>{u.phase==='Preseason'?'OPENING WEEK':`WEEK ${u.seasonState?.week||0} OF 18`}</b></div><button className="quick-sim" onClick={()=>run('week')}>Simulate next week <span>›</span></button><button className="quick-sim" onClick={()=>run('four')}>Simulate four weeks <span>›</span></button><button className="quick-sim strong" onClick={()=>run('end')}>Simulate to season end <span>›</span></button></div></div><div className="two-col"><Panel title="NFL pulse" eyebrow="POWER TABLE"><table><thead><tr><th>#</th><th>Team</th><th>W-L</th><th>PF</th><th>STR</th></tr></thead><tbody>{nfl.slice(0,8).map((t,i)=><tr key={t.id} onClick={()=>openTeam(t.id)}><td>{i+1}</td><td><div className="team-cell"><TeamMark team={t} size={28}/><b>{t.name}</b></div></td><td>{teamRecord(t)}</td><td>{t.current.pf}</td><td>{getTeamStrength(u,t.id)}</td></tr>)}</tbody></table></Panel><Panel title="Top stories" eyebrow="ESPN · CHRONICLE WIRE"><div className="news-stack">{u.news.slice(0,7).map(n=><button className="news-item" key={n.id} onClick={()=>n.playerId?openPlayer(n.playerId):n.teamId?openTeam(n.teamId):null}><span className={`news-type ${n.importance>=85?'hot':''}`}>{n.type}</span><div><b>{n.title}</b><p>{n.body}</p></div><time>Y{n.year}</time></button>)}</div></Panel></div><div className="three-col"><Panel title="College top 5" eyebrow="PROGRAM RANKINGS">{college.slice(0,5).map((t,i)=><button className="rank-row" key={t.id} onClick={()=>openTeam(t.id)}><strong>{i+1}</strong><TeamMark team={t} size={30}/><span><b>{t.name}</b><small>{t.conference}</small></span><em>{teamRecord(t)}</em></button>)}</Panel><Panel title="Players to know" eyebrow="CURRENT SEASON">{leaders.map(p=><button className="player-row" key={p.id} onClick={()=>openPlayer(p.id)}><span className="pos">{p.position}</span><span><b>{p.name}</b><small>{findTeam(u,p.teamId)?.name||'Free Agent'} · {statLine(p)}</small></span>{p.revealed?<RarityPill rarity={p.trueRarity} compact/>:<span className="mystery-tag">SCOUT</span>}</button>)}</Panel><Panel title="Offseason watch" eyebrow="ALWAYS AVAILABLE"><p className="explain">The Offseason screen remains accessible all year. It retains the previous cycle and previews the next one: coach market, transfers, retirements, free agency, draft, trades and the new freshman class.</p><div className="god-key"><span>PHASE</span><b>{u.phase}</b><span>NEXT</span><b>{u.phase==='Regular Season'?'Season completion':u.phase}</b></div></Panel></div></div>
}

function AwardsSummary({u,latest,openPlayer}){const rows=[['NFL MVP',latest?.NFL?.awards?.mvpId],['NFL OPOY',latest?.NFL?.awards?.opoyId],['NFL DPOY',latest?.NFL?.awards?.dpoyId],['Heisman',latest?.COLLEGE?.awards?.mvpId],['College DPOY',latest?.COLLEGE?.awards?.dpoyId],['UFL MVP',latest?.UFL?.awards?.mvpId]];return <Panel title="Individual honors" eyebrow={`YEAR ${latest?.year||u.year} AWARDS`}><div className="award-grid">{rows.map(([label,id])=>{const p=findPlayer(u,id);return <button key={label} onClick={()=>p&&openPlayer(p.id)}><span>{label}</span><b>{p?.name||'—'}</b><small>{p?`${p.position} · ${findTeam(u,p.teamId)?.name||'—'}`:''}</small></button>})}</div></Panel>}

function LeaguePage({u,league,openTeam,openPlayer}){const[tab,setTab]=useState('Standings'),teams=getStandings(u,league),isCollege=league==='COLLEGE',players=u.players.filter(p=>!p.retired&&p.league===league);return <div className="page"><div className="page-title"><div><div className="eyebrow">COMPETITION</div><h1>{leagueName(league)}</h1><p>{isCollege?'100-program feeder universe with hidden prospect truth.':league==='NFL'?'32 franchises, cap pressure and the championship summit.':'Development, second chances and another professional title race.'}</p></div><Segmented value={tab} onChange={setTab} items={['Standings','Games','Stats','Teams','History',...(isCollege?['Prospects']:[])]}/></div>{tab==='Standings'&&<Panel title={isCollege?'Program rankings':'Standings'} eyebrow={`YEAR ${u.year} · ${league}`}><table><thead><tr><th>#</th><th>Team</th>{league==='NFL'&&<><th>Conf.</th><th>Div.</th></>}<th>W-L</th><th>PF</th><th>PA</th><th>Diff</th><th>Strength</th></tr></thead><tbody>{teams.map((t,i)=><tr key={t.id} onClick={()=>openTeam(t.id)}><td>{i+1}</td><td><div className="team-cell"><TeamMark team={t} size={28}/><b>{t.name}</b></div></td>{league==='NFL'&&<><td>{t.conference}</td><td>{t.division}</td></>}<td>{teamRecord(t)}</td><td>{t.current.pf}</td><td>{t.current.pa}</td><td className={t.current.pf-t.current.pa>=0?'positive':'negative'}>{t.current.pf-t.current.pa>=0?'+':''}{t.current.pf-t.current.pa}</td><td>{getTeamStrength(u,t.id)}</td></tr>)}</tbody></table></Panel>}{tab==='Games'&&<GamesTable u={u} league={league} openTeam={openTeam}/>} {tab==='Stats'&&<StatsTable u={u} players={players} openPlayer={openPlayer}/>} {tab==='Teams'&&<div className="team-grid">{teams.map(t=><button className="team-card" key={t.id} style={{'--accent':t.primary}} onClick={()=>openTeam(t.id)}><TeamMark team={t} size={44}/><span><b>{t.name}</b><small>{isCollege?t.conference:`${teamRecord(t)} · ${getTeamStrength(u,t.id)} STR`}</small></span>{isCollege&&<em>{t.prestige} PRESTIGE</em>}</button>)}</div>} {tab==='History'&&<LeagueHistory u={u} league={league} openTeam={openTeam} openPlayer={openPlayer}/>} {tab==='Prospects'&&<Prospects u={u} openPlayer={openPlayer}/>}</div>}
function GamesTable({u,league,openTeam,teamId=null}){let games=u.currentGames.filter(g=>g.league===league&&(!teamId||g.homeId===teamId||g.awayId===teamId)).slice().sort((a,b)=>b.round-a.round);return <Panel title="Current-season games" eyebrow="GAME DETAIL RETAINED UNTIL NEXT YEAR"><table><thead><tr><th>Stage</th><th>Round</th><th>Away</th><th>Score</th><th>Home</th><th>Yards</th></tr></thead><tbody>{games.map(g=>{const h=findTeam(u,g.homeId),a=findTeam(u,g.awayId);return <tr key={g.id}><td>{g.stage}</td><td>{g.round}</td><td onClick={()=>openTeam(a.id)}><b>{a.name}</b></td><td><b>{g.awayScore}–{g.homeScore}</b></td><td onClick={()=>openTeam(h.id)}><b>{h.name}</b></td><td>{g.awayBox.passYards+g.awayBox.rushYards}–{g.homeBox.passYards+g.homeBox.rushYards}</td></tr>})}{!games.length&&<tr><td colSpan="6"><Empty>No games in the current season yet.</Empty></td></tr>}</tbody></table></Panel>}
function LeagueHistory({u,league,openTeam,openPlayer}){const rows=u.seasonHistory.map(y=>({year:y.year,data:y[league]||{championId:league==='NFL'?y.nflChampionId:league==='UFL'?y.uflChampionId:y.collegeChampionId,awards:{mvpId:league==='NFL'?y.nflMvpId:league==='UFL'?y.uflMvpId:y.heismanId}}}));return <Panel title="Competition history" eyebrow="PERMANENT YEARBOOK"><table><thead><tr><th>Year</th><th>Champion</th><th>Record</th><th>Runner-up</th><th>Final</th><th>Best regular season</th><th>{league==='COLLEGE'?'Heisman':'MVP'}</th><th>OPOY</th><th>DPOY</th>{league==='NFL'&&<th>ROY</th>}<th>Coach</th></tr></thead><tbody>{rows.map(({year,data})=><tr key={year}><td>Year {year}</td><td onClick={()=>data.championId&&openTeam(data.championId)}><b>{findTeam(u,data.championId)?.name||'—'}</b></td><td>{data.championRecord||'—'}</td><td onClick={()=>data.runnerUpId&&openTeam(data.runnerUpId)}>{findTeam(u,data.runnerUpId)?.name||'—'}</td><td><b>{data.finalScore||'—'}</b></td><td onClick={()=>data.bestRecordTeamId&&openTeam(data.bestRecordTeamId)}>{findTeam(u,data.bestRecordTeamId)?.name||'—'} <small className="block">{data.bestRecord||''}</small></td><td onClick={()=>data.awards?.mvpId&&openPlayer(data.awards.mvpId)}><b>{findPlayer(u,data.awards?.mvpId)?.name||'—'}</b></td><td onClick={()=>data.awards?.opoyId&&openPlayer(data.awards.opoyId)}>{findPlayer(u,data.awards?.opoyId)?.name||'—'}</td><td onClick={()=>data.awards?.dpoyId&&openPlayer(data.awards.dpoyId)}>{findPlayer(u,data.awards?.dpoyId)?.name||'—'}</td>{league==='NFL'&&<td onClick={()=>data.awards?.royId&&openPlayer(data.awards.royId)}>{findPlayer(u,data.awards?.royId)?.name||'—'}</td>}<td>{data.awards?.coachId?getAllCoaches(u).find(c=>c.id===data.awards.coachId)?.name||'Recorded coach':'—'}</td></tr>)}{!rows.length&&<tr><td colSpan={league==='NFL'?11:10}><Empty>No completed seasons yet.</Empty></td></tr>}</tbody></table></Panel>}
function StatsTable({u,players,openPlayer}){const[cat,setCat]=useState('Passing');const sorted=[...players].sort((a,b)=>{const s=x=>x.currentSeason||x.stats.seasons.at(-1)||{};return cat==='Passing'?(s(b).passYards||0)-(s(a).passYards||0):cat==='Rushing'?(s(b).rushYards||0)-(s(a).rushYards||0):cat==='Receiving'?(s(b).recYards||0)-(s(a).recYards||0):cat==='Sacks'?(s(b).sacks||0)-(s(a).sacks||0):(s(b).tackles||0)-(s(a).tackles||0)}).slice(0,40);return <Panel title={`${cat} leaders`} eyebrow="CURRENT SEASON" action={<Segmented value={cat} onChange={setCat} items={['Passing','Rushing','Receiving','Sacks','Tackles']}/>}><table><thead><tr><th>#</th><th>Player</th><th>Team</th><th>Pos</th><th>{cat}</th><th>TD / INT</th></tr></thead><tbody>{sorted.map((p,i)=>{const s=p.currentSeason||p.stats.seasons.at(-1)||{},v=cat==='Passing'?s.passYards:cat==='Rushing'?s.rushYards:cat==='Receiving'?s.recYards:cat==='Sacks'?s.sacks:s.tackles;return <tr key={p.id} onClick={()=>openPlayer(p.id)}><td>{i+1}</td><td><b>{p.name}</b></td><td>{findTeam(u,p.teamId)?.name||'—'}</td><td>{p.position}</td><td>{num(v||0)}</td><td>{cat==='Passing'?`${s.passTD||0} / ${s.interceptions||0}`:`${(s.rushTD||0)+(s.recTD||0)} TD`}</td></tr>})}</tbody></table></Panel>}
function Prospects({u,openPlayer}){const p=u.players.filter(x=>!x.retired&&x.league==='COLLEGE'&&!x.revealed).sort((a,b)=>(b.scouting?.expectedTier||0)-(a.scouting?.expectedTier||0)).slice(0,100);return <Panel title="Draft radar" eyebrow="TRUE TALENT SEALED"><table><thead><tr><th>#</th><th>Prospect</th><th>School</th><th>Class</th><th>Public range</th><th>Probability band</th></tr></thead><tbody>{p.map((x,i)=><tr key={x.id} onClick={()=>openPlayer(x.id)}><td>{i+1}</td><td><b>{x.name}</b><small className="block">{x.position}</small></td><td>{findTeam(u,x.teamId)?.name}</td><td>{cls(x.collegeYear)}</td><td>{x.scouting?.label}</td><td className="prob-cell"><ProbabilityStrip probs={x.scouting?.probs}/></td></tr>)}</tbody></table></Panel>}

function PlayersPage({u,openPlayer}){const[q,setQ]=useState(''),[league,setLeague]=useState('ALL'),[pos,setPos]=useState('ALL'),[status,setStatus]=useState('Active'),[sort,setSort]=useState('Rarity');let list=u.players.filter(p=>(status==='All'||(status==='Active'&&!p.retired)||(status==='Retired'&&p.retired))&&(league==='ALL'||p.league===league)&&(pos==='ALL'||p.position===pos)&&(!q||p.name.toLowerCase().includes(q.toLowerCase())));const talent=p=>p.revealed?rr(p.trueRarity):(p.scouting?.expectedTier||0);list.sort((a,b)=>sort==='Rarity'?talent(b)-talent(a)||b.overall-a.overall:sort==='Overall'?b.overall-a.overall:sort==='Age'?a.age-b.age:a.name.localeCompare(b.name));return <div className="page"><div className="page-title"><div><div className="eyebrow">DATABASE</div><h1>Players</h1><p>Active, retired or everyone. Hidden college players sort by their public scouting expectation—not their sealed true rarity.</p></div></div><div className="filters"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search player…"/><Segmented value={status} onChange={setStatus} items={['Active','Retired','All']}/><Segmented value={league} onChange={setLeague} items={['ALL','NFL','COLLEGE','UFL']}/><select value={pos} onChange={e=>setPos(e.target.value)}><option>ALL</option>{['QB','HB','FB','WR','TE','OT','OG','C','EDGE','DT','LB','CB','S','K','P'].map(x=><option key={x}>{x}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option>Rarity</option><option>Overall</option><option>Age</option><option>Name</option></select></div><Panel title={`${list.length} matching players`} eyebrow="VISIBLE DATABASE"><table><thead><tr><th>Player</th><th>Status</th><th>Pos</th><th>Team</th><th>Age</th><th>Talent view</th><th>Latest</th></tr></thead><tbody>{list.slice(0,300).map(p=><tr key={p.id} onClick={()=>openPlayer(p.id)}><td><b>{p.name}</b></td><td>{p.retired?'Retired':'Active'}</td><td>{p.position}</td><td>{findTeam(u,p.teamId)?.name||'Free Agent'}</td><td>{p.age}</td><td>{p.revealed?<RarityPill rarity={p.trueRarity} compact/>:<span className="scout-inline">{p.scouting?.label}</span>}</td><td>{p.stats.seasons.length||p.currentSeason?statLine(p):'No completed season'}</td></tr>)}</tbody></table></Panel></div>}

const STAT_CATS={
  'Passing Yards':'passYards','Passing TD':'passTD','Rushing Yards':'rushYards','Rushing TD':'rushTD','Receiving Yards':'recYards','Receiving TD':'recTD','Sacks':'sacks','Tackles':'tackles','Interceptions':'defInterceptions'
};
function StatsPage({u,openPlayer}){const[scope,setScope]=useState('Season'),[league,setLeague]=useState('NFL'),[cat,setCat]=useState('Passing Yards');const key=STAT_CATS[cat];let list=u.players.filter(p=>(league==='ALL'||p.league===league)&&(scope==='Career'||!p.retired));const value=p=>scope==='Career'?(p.stats.career?.[key]||0):((p.currentSeason?.[key]??p.stats.seasons.at(-1)?.[key])||0);list.sort((a,b)=>value(b)-value(a));return <div className="page"><div className="page-title"><div><div className="eyebrow">STATISTICAL DATABASE</div><h1>Stats</h1><p>Separate current-season and permanent career leaderboards across all three competitions.</p></div><div className="stats-controls"><Segmented value={scope} onChange={setScope} items={['Season','Career']}/><Segmented value={league} onChange={setLeague} items={['NFL','COLLEGE','UFL','ALL']}/><select value={cat} onChange={e=>setCat(e.target.value)}>{Object.keys(STAT_CATS).map(x=><option key={x}>{x}</option>)}</select></div></div><Panel title={`${scope} ${cat}`} eyebrow="TOP 100"><table><thead><tr><th>#</th><th>Player</th><th>Team</th><th>Pos</th><th>Rarity</th><th>{cat}</th></tr></thead><tbody>{list.slice(0,100).map((p,i)=><tr key={p.id} onClick={()=>openPlayer(p.id)}><td>{i+1}</td><td><b>{p.name}</b></td><td>{findTeam(u,p.teamId)?.name||'—'}</td><td>{p.position}</td><td>{p.revealed?<RarityPill rarity={p.trueRarity} compact/>:<span className="mystery-tag">SCOUT</span>}</td><td><b>{num(value(p))}</b></td></tr>)}</tbody></table></Panel></div>}

function CoachesPage({u}){const[role,setRole]=useState('HC'),[league,setLeague]=useState('ALL'),[status,setStatus]=useState('Active'),[sort,setSort]=useState('Rarity');let rows=getAllCoaches(u).filter(s=>(role==='ALL'||s.role===role)&&(league==='ALL'||s.currentLeague===league)&&(status==='All'||(status==='Active'&&s.currentTeamId)||(status==='Free'&&!s.currentTeamId)));rows.sort((a,b)=>sort==='Rarity'?rr(b.rarity)-rr(a.rarity)||b.overall-a.overall:b.overall-a.overall);const counts=RARITIES.reduce((o,r)=>({...o,[r]:getAllCoaches(u).filter(s=>s.rarity===r&&s.currentTeamId).length}),{});return <div className="page"><div className="page-title"><div><div className="eyebrow">STAFF ECOSYSTEM</div><h1>Coaches</h1><p>The coaching market is visible: quality, role, style, salary, contract, movement and free-agent status.</p></div></div><div className="rarity-board coach-rarity">{['Generational','Legend','Epic','Rare','Uncommon'].map(r=><div key={r}><RarityPill rarity={r}/><b>{counts[r]}</b><small>active coaches</small></div>)}</div><div className="filters"><Segmented value={role} onChange={setRole} items={['HC','OC','DC','ALL']}/><Segmented value={status} onChange={setStatus} items={['Active','Free','All']}/><Segmented value={league} onChange={setLeague} items={['ALL','NFL','COLLEGE','UFL','FREE']}/><select value={sort} onChange={e=>setSort(e.target.value)}><option>Rarity</option><option>Overall</option></select></div><Panel title={`${rows.length} coaches`} eyebrow="COACH DATABASE"><table><thead><tr><th>Coach</th><th>Role</th><th>Team</th><th>Tier</th><th>OVR</th><th>Style</th><th>Contract</th><th>Salary</th><th>Career</th></tr></thead><tbody>{rows.map(s=><tr key={`${s.id}-${s.currentTeamId||'FA'}`}><td><b>{s.name}</b></td><td>{s.role}</td><td>{findTeam(u,s.currentTeamId)?.name||'Coach Free Market'}</td><td><RarityPill rarity={s.rarity} compact/></td><td>{s.overall}</td><td>{s.style}</td><td>{s.currentTeamId?`${s.contractYears||0} yrs`:'FREE'}</td><td>{s.currentTeamId?money(s.salary):'—'}</td><td>{s.yearsCareer}/{s.careerLength} yrs</td></tr>)}</tbody></table></Panel></div>}

function Market({u,openPlayer,openTeam}){const[tab,setTab]=useState('Cap'),nfl=[...u.teams.nfl].sort((a,b)=>(b.capLimit-b.capUsed)-(a.capLimit-a.capUsed)),exp=u.players.filter(p=>!p.retired&&p.league==='NFL'&&p.contract?.years===1).sort((a,b)=>rr(b.trueRarity)-rr(a.trueRarity)||b.overall-a.overall).slice(0,100),free=u.players.filter(p=>!p.retired&&!p.teamId&&p.league!=='COLLEGE').sort((a,b)=>b.overall-a.overall).slice(0,100),pros=u.players.filter(p=>!p.retired&&p.league==='COLLEGE'&&!p.revealed&&p.collegeYear>=3).sort((a,b)=>(b.scouting?.expectedTier||0)-(a.scouting?.expectedTier||0)).slice(0,100),ret=u.players.filter(p=>!p.retired&&p.league!=='COLLEGE'&&(p.proYear||0)>=p.careerYears-1).sort((a,b)=>b.overall-a.overall).slice(0,100),fresh=u.players.filter(p=>!p.retired&&p.league==='COLLEGE'&&p.collegeYear===1).sort((a,b)=>(b.scouting?.expectedTier||0)-(a.scouting?.expectedTier||0)).slice(0,100);return <div className="page"><div className="page-title"><div><div className="eyebrow">ROSTER ECONOMY</div><h1>Market</h1><p>Cap room, expiring contracts, transactions, draft supply and career-end pressure.</p></div><Segmented value={tab} onChange={setTab} items={['Cap','Contracts','Transactions','Draft Board','Retiring','New Class']}/></div>{tab==='Cap'&&<Panel title="Salary cap" eyebrow="NFL · TRACKED ROSTER CAP"><table><thead><tr><th>Team</th><th>Limit</th><th>Used</th><th>Room</th><th>Load</th></tr></thead><tbody>{nfl.map(t=><tr key={t.id} onClick={()=>openTeam(t.id)}><td><b>{t.name}</b></td><td>{money(t.capLimit)}</td><td>{money(t.capUsed)}</td><td>{money(t.capLimit-t.capUsed)}</td><td><div className="capbar"><span style={{width:`${Math.min(100,t.capUsed/t.capLimit*100)}%`}}/></div></td></tr>)}</tbody></table></Panel>}{tab==='Contracts'&&<div className="two-col"><Panel title="Expiring after this year" eyebrow="NFL"><div className="scroll-list">{exp.map(p=><button className="player-row" key={p.id} onClick={()=>openPlayer(p.id)}><span className="pos">{p.position}</span><span><b>{p.name}</b><small>{findTeam(u,p.teamId)?.name} · {money(p.contract?.annual)}</small></span><RarityPill rarity={p.trueRarity} compact/></button>)}</div></Panel><Panel title="Current free agents" eyebrow="PRO MARKET"><div className="scroll-list">{free.map(p=><button className="player-row" key={p.id} onClick={()=>openPlayer(p.id)}><span className="pos">{p.position}</span><span><b>{p.name}</b><small>{p.age} years old</small></span><RarityPill rarity={p.trueRarity} compact/></button>)}{!free.length&&<Empty>No tracked free agents right now.</Empty>}</div></Panel></div>}{tab==='Transactions'&&<Panel title="Transaction register" eyebrow="PERMANENT MARKET LOG"><table><thead><tr><th>Year</th><th>Type</th><th>Subject</th><th>From</th><th>To</th><th>Detail</th></tr></thead><tbody>{u.transactions.slice(0,200).map((x,i)=>{const p=findPlayer(u,x.playerId);return <tr key={`${x.year}-${x.type}-${i}`} onClick={()=>p&&openPlayer(p.id)}><td>Y{x.year}</td><td>{x.type}</td><td><b>{p?.name||x.name||'Staff'}</b></td><td>{findTeam(u,x.fromId)?.name||'—'}</td><td>{findTeam(u,x.toId)?.name||'—'}</td><td>{x.detail||''}</td></tr>})}</tbody></table></Panel>}{tab==='Draft Board'&&<Panel title="Next draft radar" eyebrow="PUBLIC INFORMATION ONLY"><table><thead><tr><th>#</th><th>Prospect</th><th>School</th><th>Class</th><th>Public range</th><th>Probability</th></tr></thead><tbody>{pros.map((p,i)=><tr key={p.id} onClick={()=>openPlayer(p.id)}><td>{i+1}</td><td><b>{p.name}</b> · {p.position}</td><td>{findTeam(u,p.teamId)?.name}</td><td>{cls(p.collegeYear)}</td><td>{p.scouting?.label}</td><td className="prob-cell"><ProbabilityStrip probs={p.scouting?.probs}/></td></tr>)}</tbody></table></Panel>}{tab==='Retiring'&&<Panel title="Career-end watch" eyebrow="GOD VIEW"><table><thead><tr><th>Player</th><th>Team</th><th>Pos</th><th>Tier</th><th>Pro Year</th><th>Career Script</th></tr></thead><tbody>{ret.map(p=><tr key={p.id} onClick={()=>openPlayer(p.id)}><td><b>{p.name}</b></td><td>{findTeam(u,p.teamId)?.name||'—'}</td><td>{p.position}</td><td><RarityPill rarity={p.trueRarity} compact/></td><td>{p.proYear}</td><td>{p.careerYears}</td></tr>)}</tbody></table></Panel>}{tab==='New Class'&&<Panel title="Freshman class" eyebrow="THE ONLY PLAYER SPAWN POINT"><table><thead><tr><th>Player</th><th>Position</th><th>Program</th><th>Public range</th><th>Probability band</th></tr></thead><tbody>{fresh.map(p=><tr key={p.id} onClick={()=>openPlayer(p.id)}><td><b>{p.name}</b></td><td>{p.position}</td><td>{findTeam(u,p.teamId)?.name}</td><td>{p.scouting?.label}</td><td className="prob-cell"><ProbabilityStrip probs={p.scouting?.probs}/></td></tr>)}</tbody></table></Panel>}</div>}

function Draft({u,openPlayer}){const reveals=u.lastDraftReveal||[];return <div className="page"><div className="page-title draft-title"><div><div className="eyebrow">GOD VIEW · POST-DRAFT TRUTH</div><h1>Draft Reveal</h1><p>Public probability → actual rarity → hidden career script. Teams still do not know the future path.</p></div><div className="reveal-legend"><span>PUBLIC SCOUTING</span><i>→</i><span>TRUE RARITY</span><i>→</i><span>CAREER ARC</span></div></div>{!reveals.length?<Panel title="No draft completed" eyebrow="DRAFT"><Empty>The reveal appears when the Draft stage of the offseason is run.</Empty></Panel>:<Panel title={`Year ${reveals[0].year} NFL Draft`} eyebrow={`${reveals.length} PICKS REVEALED`}><div className="draft-list">{reveals.map(r=>{const p=findPlayer(u,r.playerId),team=findTeam(u,r.teamId),college=findTeam(u,r.collegeId),delta=rr(r.actualRarity)-(r.scouting?.expectedTier||0);return <button key={r.playerId} className={`draft-row ${delta>1.15?'steal':delta<-.9?'bust':''}`} onClick={()=>openPlayer(r.playerId)}><strong className="pick">{r.pick}</strong><TeamMark team={team} size={34}/><div className="draft-name"><b>{p?.name}</b><small>{p?.position} · {college?.name}</small></div><div className="draft-scout"><span>{r.scouting?.label}</span><ProbabilityStrip probs={r.scouting?.probs}/></div><div className="truth"><RarityPill rarity={r.actualRarity}/><b>{r.developmentPath}</b><small>{r.careerYears} pro years scripted</small></div><em>{delta>1.15?'STEAL':delta<-.9?'BAD READ':'FAIR READ'}</em></button>})}</div></Panel>}</div>}

function eventName(u,e){return findPlayer(u,e.playerId)?.name||e.name||'—'}
function Offseason({u,openPlayer,openTeam,run}){const live=u.offseasonState,archive=u.offseasonHistory?.[0],data=live||archive,idx=live?.stageIndex||0;const[tab,setTab]=useState('Summary');const tabs=['Summary','Coach Market','Transfers','Retirements','Free Agency','Draft','Trades','New Class'];return <div className="page"><div className="page-title"><div><div className="eyebrow">YEAR-ROUND FRONT OFFICE HUB</div><h1>Offseason</h1><p>This screen remains available during the season. It shows the last completed market cycle, and becomes live once the current season ends.</p></div><Segmented value={tab} onChange={setTab} items={tabs}/></div><div className="offseason-status"><div><span>CURRENT UNIVERSE PHASE</span><b>{u.phase}</b><small>{u.phase==='Regular Season'?`Year ${u.year} offseason has not begun. Previous cycle remains below.`:u.phase==='Offseason'?`Stage ${idx+1} of ${OFFSEASON_STAGES.length}: ${OFFSEASON_STAGES[idx]||'Complete'}`:u.phase==='Season Complete'?'Results are final. Enter the offseason when ready.':u.phase==='Ready for Next Season'?`Year ${u.year} offseason complete.`:'Opening season.'}</small></div>{u.phase==='Season Complete'&&<button className="advance" onClick={()=>run('offseason')}>ADVANCE TO OFFSEASON ›</button>}{u.phase==='Offseason'&&<button className="advance" onClick={()=>run('stage')}>RUN {OFFSEASON_STAGES[idx]} ›</button>}{u.phase==='Ready for Next Season'&&<button className="advance" onClick={()=>run('next')}>START YEAR {u.year+1} ›</button>}</div><div className="offseason-rail">{OFFSEASON_STAGES.map((s,i)=><div key={s} className={live?(i<idx?'done':i===idx&&u.phase==='Offseason'?'current':''):archive?'done':''}><b>{i+1}</b><span>{s}</span></div>)}</div>{!data&&<Panel title="No offseason history yet" eyebrow="YEAR 1"><Empty>Finish Year 1 to create the first offseason ledger. The stages above show the permanent sequence.</Empty></Panel>}{data&&tab==='Summary'&&<OffseasonSummary u={u} data={data} openPlayer={openPlayer} openTeam={openTeam}/>} {data&&tab==='Coach Market'&&<EventTable title="Coach market" rows={data.events?.coachMarket||[]} cols={['Type','Coach','Role','From','To','Contract']} render={(e,i)=><tr key={i}><td>{e.type}</td><td><b>{e.name}</b></td><td>{e.role}</td><td>{findTeam(u,e.fromId)?.name||'Market'}</td><td>{findTeam(u,e.toId||e.teamId)?.name||'—'}</td><td>{e.years?`${e.years} yrs · ${money(e.salary)}`:'—'}</td></tr>}/>} {data&&tab==='Transfers'&&<EventTable title="College transfer portal" rows={data.events?.transfers||[]} cols={['Player','From','To','Public scouting']} render={(e,i)=><tr key={i} onClick={()=>openPlayer(e.playerId)}><td><b>{eventName(u,e)}</b></td><td>{findTeam(u,e.fromId)?.name}</td><td>{findTeam(u,e.toId)?.name}</td><td>{e.scouting}</td></tr>}/>} {data&&tab==='Retirements'&&<div className="two-col"><EventTable title="Retirements" rows={data.events?.retirements||[]} cols={['Player','Team','Tier','Career']} render={(e,i)=><tr key={i} onClick={()=>openPlayer(e.playerId)}><td><b>{eventName(u,e)}</b></td><td>{findTeam(u,e.teamId)?.name||'—'}</td><td><RarityPill rarity={e.rarity} compact/></td><td>{e.careerYears} pro years</td></tr>}/><EventTable title="Draft declarations" rows={data.events?.declarations||[]} cols={['Player','College','Public range']} render={(e,i)=><tr key={i} onClick={()=>openPlayer(e.playerId)}><td><b>{eventName(u,e)}</b></td><td>{findTeam(u,e.collegeId)?.name}</td><td>{e.scouting}</td></tr>}/></div>} {data&&tab==='Free Agency'&&<EventTable title="Free agency & renewals" rows={data.events?.freeAgency||[]} cols={['Type','Player','From','To','Deal']} render={(e,i)=><tr key={i} onClick={()=>openPlayer(e.playerId)}><td>{e.type}</td><td><b>{eventName(u,e)}</b></td><td>{findTeam(u,e.fromId)?.name||'—'}</td><td>{findTeam(u,e.toId||e.teamId)?.name||'—'}</td><td>{e.years?`${e.years} yrs · ${money(e.annual)}`:'—'}</td></tr>}/>} {data&&tab==='Draft'&&<EventTable title="NFL Draft" rows={data.events?.draft||[]} cols={['Pick','Player','NFL team','College','Expected','Actual','Career']} render={(e,i)=>{const p=findPlayer(u,e.playerId);return <tr key={i} onClick={()=>openPlayer(e.playerId)}><td>#{e.pick}</td><td><b>{p?.name}</b></td><td>{findTeam(u,e.teamId)?.name}</td><td>{findTeam(u,e.collegeId)?.name}</td><td>{e.scouting?.label}</td><td><RarityPill rarity={e.actualRarity} compact/></td><td>{e.developmentPath} · {e.careerYears} yrs</td></tr>}}/>} {data&&tab==='Trades'&&<EventTable title="Trades & UFL movement" rows={data.events?.trades||[]} cols={['Player','From','To','Detail']} render={(e,i)=><tr key={i} onClick={()=>openPlayer(e.playerId)}><td><b>{eventName(u,e)}</b></td><td>{findTeam(u,e.fromId)?.name||'—'}</td><td>{findTeam(u,e.toId)?.name||'—'}</td><td>{e.detail||''}</td></tr>}/>} {data&&tab==='New Class'&&<EventTable title="New freshman class" rows={data.events?.spawned||[]} cols={['Player','College','Position','Public range']} render={(e,i)=><tr key={i} onClick={()=>openPlayer(e.playerId)}><td><b>{eventName(u,e)}</b></td><td>{findTeam(u,e.collegeId)?.name}</td><td>{e.position}</td><td>{e.scouting}</td></tr>}/>}</div>}
function EventTable({title,rows,cols,render}){return <Panel title={title} eyebrow={`${rows.length} EVENTS`}><table><thead><tr>{cols.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map(render)}{!rows.length&&<tr><td colSpan={cols.length}><Empty>No events recorded for this stage yet.</Empty></td></tr>}</tbody></table></Panel>}
function OffseasonSummary({u,data,openPlayer,openTeam}){const e=data.events||{},cards=[['Coach moves',e.coachMarket?.length||0],['Transfers',e.transfers?.length||0],['Retirements',e.retirements?.length||0],['Free-agent events',e.freeAgency?.length||0],['Draft picks',e.draft?.length||0],['Freshmen spawned',e.spawned?.length||0]];return <>{data.summary&&<><div className="winner-grid"><CompetitionWinner u={u} league="NFL" summary={data.summary.NFL} openTeam={openTeam} openPlayer={openPlayer}/><CompetitionWinner u={u} league="COLLEGE" summary={data.summary.COLLEGE} openTeam={openTeam} openPlayer={openPlayer}/><CompetitionWinner u={u} league="UFL" summary={data.summary.UFL} openTeam={openTeam} openPlayer={openPlayer}/></div><AwardsSummary u={u} latest={data.summary} openPlayer={openPlayer}/></>}<div className="summary-metrics">{cards.map(([a,b])=><Metric key={a} label={a} value={b}/>)}</div><Panel title={`Year ${data.year} offseason ledger`} eyebrow="EVERY PHASE RETAINED"><p className="explain">This ledger persists after the season starts, so you can always reconstruct how the current rosters were built.</p><div className="ledger-grid">{Object.entries(e).map(([k,v])=><div key={k}><span>{k.replace(/([A-Z])/g,' $1')}</span><b>{Array.isArray(v)?v.length:0}</b></div>)}</div></Panel></>}

function ESPN({u,openPlayer,openTeam}){return <div className="page"><div className="page-title"><div><div className="eyebrow">CHRONICLE WIRE</div><h1>ESPN</h1><p>Championships, awards, trades, draft shocks, coaching changes and records.</p></div></div><div className="news-grid">{u.news.map(n=><button className={`story ${n.importance>=90?'lead':''}`} key={n.id} onClick={()=>n.playerId?openPlayer(n.playerId):n.teamId?openTeam(n.teamId):null}><span>{n.type} · YEAR {n.year}</span><h3>{n.title}</h3><p>{n.body}</p><b>{n.importance>=90?'TOP STORY':'READ STORY'} ›</b></button>)}</div></div>}
function Records({u,openPlayer,openTeam}){const[league,setLeague]=useState('NFL'),[cat,setCat]=useState('Passing Yards'),cats=['Passing Yards','Rushing Yards','Receiving Yards','Sacks','Team Points','Team Yards'],rows=u.records.filter(r=>r.league===league&&r.category===cat).sort((a,b)=>b.value-a.value);return <div className="page"><div className="page-title"><div><div className="eyebrow">ALMANAC</div><h1>Records</h1><p>Game detail disappears after the current year; record performances do not.</p></div><Segmented value={league} onChange={setLeague} items={['NFL','COLLEGE','UFL']}/></div><Panel title={cat} eyebrow={`TOP 10 · ${league}`} action={<select value={cat} onChange={e=>setCat(e.target.value)}>{cats.map(x=><option key={x}>{x}</option>)}</select>}><table><thead><tr><th>#</th><th>Holder</th><th>Value</th><th>Year</th><th>Stage</th><th>Round</th></tr></thead><tbody>{rows.map((r,i)=>{const p=r.playerId?findPlayer(u,r.playerId):null,t=findTeam(u,r.teamId);return <tr key={`${r.gameId}-${i}`} onClick={()=>p?openPlayer(p.id):t&&openTeam(t.id)}><td>{i+1}</td><td><b>{p?.name||t?.name||'Unknown'}</b></td><td>{num(r.value)}</td><td>Year {r.year}</td><td>{r.stage}</td><td>{r.round}</td></tr>})}{!rows.length&&<tr><td colSpan="6"><Empty>No records yet.</Empty></td></tr>}</tbody></table></Panel></div>}
function Universe({u,setU}){const counts=rarityCounts(u.players),target={Generational:3,Legend:'10–15',Epic:'~20',Rare:'~50',Uncommon:'~80'},gens=u.players.filter(p=>!p.retired&&p.trueRarity==='Generational'&&p.revealed),sealed=u.players.filter(p=>!p.retired&&p.league==='COLLEGE'&&!p.revealed).length;return <div className="page"><div className="page-title"><div><div className="eyebrow">HISTORY ENGINE</div><h1>Universe</h1><p>Seeded world state, rarity control and permanent historical layer.</p></div></div><div className="rarity-board">{['Generational','Legend','Epic','Rare','Uncommon'].map(r=><div key={r}><RarityPill rarity={r}/><b>{counts[r]}</b><small>target {target[r]}</small></div>)}</div><Panel title="Known Generational players" eyebrow="COLLEGE TRUE TIER REMAINS SEALED"><table><thead><tr><th>Player</th><th>Age</th><th>League</th><th>Team</th><th>Pro Year</th></tr></thead><tbody>{gens.map(p=><tr key={p.id}><td><b>{p.name}</b></td><td>{p.age}</td><td>{p.league}</td><td>{findTeam(u,p.teamId)?.name}</td><td>Pro {p.proYear}</td></tr>)}</tbody></table><p className="explain">{sealed} active college prospects have sealed true tiers. This page never identifies which unrevealed prospect is secretly Generational, Legend, Epic, or anything else.</p></Panel><div className="two-col"><Panel title="Yearbook" eyebrow="CHAMPIONS & MVPs"><div className="yearbook">{u.seasonHistory.map(y=><div className="year-row" key={y.year}><strong>YEAR {y.year}</strong><span>NFL <b>{findTeam(u,y.NFL?.championId||y.nflChampionId)?.name}</b></span><span>College <b>{findTeam(u,y.COLLEGE?.championId||y.collegeChampionId)?.name}</b></span><span>MVP <b>{findPlayer(u,y.NFL?.awards?.mvpId||y.nflMvpId)?.name}</b></span></div>)}{!u.seasonHistory.length&&<Empty>No completed seasons yet.</Empty>}</div></Panel><Panel title="Simulation invariants" eyebrow="BALANCE RULES"><ul className="invariants"><li><b>College-only spawning.</b> New players enter as freshmen only.</li><li><b>Hidden prospect truth.</b> Draft AI never sees true rarity or career arc.</li><li><b>Established starting universe.</b> Two of the initial three Generational players begin in the NFL, avoiding an all-teenage elite population.</li><li><b>Elite employment floor.</b> Useful pros are actively pursued or receive UFL fallback.</li><li><b>Anti-dynasty pressure.</b> Cap churn, staff movement and award-repeat fatigue create natural resistance.</li></ul></Panel></div><SaveHub universe={u} setUniverse={setU}/></div>}

function EntityHeader({children,onBack}){return <><button className="back-btn" onClick={onBack}>‹ Back to Chronicle</button>{children}</>}
function TeamPage({u,id,onBack,openPlayer,openTeam}){const t=findTeam(u,id);const[tab,setTab]=useState('Overview');if(!t)return null;const r=getRoster(u,id).sort((a,b)=>t.league==='COLLEGE'?((b.scouting?.expectedTier||0)-(a.scouting?.expectedTier||0)):b.overall-a.overall),hist=[...(t.history?.seasons||[])].reverse();return <div className="page"><EntityHeader onBack={onBack}><div className="entity-hero team-page-hero" style={{'--accent':t.primary}}><TeamMark team={t} size={76}/><div><div className="eyebrow">{t.league} · TEAM PAGE</div><h1>{t.name}</h1><p>{t.league==='COLLEGE'?t.conference:`${t.conference||''} ${t.division||''}`}</p></div><div className="entity-metrics"><Metric label="Current record" value={teamRecord(t)}/><Metric label="Strength" value={getTeamStrength(u,id)}/><Metric label="Titles" value={t.history.championships}/>{t.league!=='COLLEGE'&&<Metric label="Cap room" value={money(t.capLimit-t.capUsed)}/>}</div></div></EntityHeader><Segmented value={tab} onChange={setTab} items={['Overview','Current Season','History','Roster','Staff']}/><div className="entity-tab">{tab==='Overview'&&<div className="two-col"><Panel title="Franchise profile" eyebrow="OVERVIEW"><div className="profile-grid"><Metric label="Popularity" value={t.popularity||'—'}/><Metric label="Prestige" value={t.prestige||'—'}/><Metric label="Playoff appearances" value={t.history.playoffs||0}/><Metric label="Championships" value={t.history.championships||0}/></div></Panel><Panel title="Top talent" eyebrow="CURRENT ROSTER">{r.slice(0,8).map(p=><button className="player-row" key={p.id} onClick={()=>openPlayer(p.id)}><span className="pos">{p.position}</span><span><b>{p.name}</b><small>{p.revealed?`OVR ${p.overall}`:p.scouting?.label}</small></span>{p.revealed?<RarityPill rarity={p.trueRarity} compact/>:<span className="mystery-tag">?</span>}</button>)}</Panel></div>}{tab==='Current Season'&&<GamesTable u={u} league={t.league} teamId={t.id} openTeam={openTeam}/>}{tab==='History'&&<Panel title="Season-by-season career" eyebrow="TEAM HISTORY"><table><thead><tr><th>Year</th><th>W-L</th><th>PF</th><th>PA</th><th>Rank</th><th>Final position</th></tr></thead><tbody>{hist.map(s=><tr key={s.year}><td>Year {s.year}</td><td><b>{s.wins}-{s.losses}</b></td><td>{s.pf}</td><td>{s.pa}</td><td>#{s.rank||'—'}</td><td><b>{s.finish||'—'}</b></td></tr>)}{!hist.length&&<tr><td colSpan="6"><Empty>No completed team seasons yet.</Empty></td></tr>}</tbody></table></Panel>}{tab==='Roster'&&<Panel title={t.league==='COLLEGE'?'Featured players':'Tracked roster'} eyebrow="PERSONNEL"><table><thead><tr><th>Player</th><th>Pos</th><th>Age</th><th>Talent</th><th>OVR</th><th>Contract</th><th>Season</th></tr></thead><tbody>{r.map(p=><tr key={p.id} onClick={()=>openPlayer(p.id)}><td><b>{p.name}</b></td><td>{p.position}</td><td>{p.age}</td><td>{p.revealed?<RarityPill rarity={p.trueRarity} compact/>:<span>{p.scouting?.label}</span>}</td><td>{p.revealed?p.overall:'—'}</td><td>{p.contract?`${p.contract.years} yrs · ${money(p.contract.annual)}`:'—'}</td><td>{statLine(p)}</td></tr>)}</tbody></table></Panel>}{tab==='Staff'&&<Panel title="Football operations" eyebrow="OWNER · GM · COACHING"><div className="staff-page-grid">{[['Owner',t.owner],['GM',t.gm],['Head Coach',t.hc],['Offensive Coordinator',t.oc],['Defensive Coordinator',t.dc]].filter(([,s])=>s).map(([label,s])=><div key={label}><span>{label}</span><h3>{s.name}</h3><RarityPill rarity={s.rarity}/><p>{s.style} · OVR {s.overall}</p><small>{s.contractYears||'—'} years · {money(s.salary)}</small></div>)}</div></Panel>}</div></div>}
function PlayerPage({u,id,onBack,openTeam}){const p=findPlayer(u,id);const[tab,setTab]=useState('Overview');if(!p)return null;const team=findTeam(u,p.teamId),college=findTeam(u,p.collegeId),hidden=p.league==='COLLEGE'&&!p.revealed,txs=u.transactions.filter(x=>x.playerId===p.id);return <div className="page"><EntityHeader onBack={onBack}><div className="entity-hero player-page-hero"><div className="player-avatar big">{p.position}</div><div><div className="eyebrow">{hidden?'COLLEGE PROSPECT · SEALED TRUTH':`${p.league} · ${p.position}`}</div><h1>{p.name}</h1><p>{team?.name||'Free Agent'}{college&&team?.id!==college.id?` · ${college.name}`:''}</p></div><div className="entity-metrics"><Metric label="Age" value={p.age}/><Metric label="Status" value={p.retired?'Retired':'Active'}/>{hidden?<Metric label="Public range" value={p.scouting?.label}/>:<><Metric label="True tier" value={p.trueRarity}/><Metric label="OVR" value={p.overall}/></>}</div></div></EntityHeader><Segmented value={tab} onChange={setTab} items={['Overview','Current Season','Career','History']}/><div className="entity-tab">{tab==='Overview'&&hidden&&<div className="two-col"><Panel title="Public scouting" eyebrow="WHAT EVERYONE KNOWS"><h3>{p.scouting?.label}</h3><ProbabilityStrip probs={p.scouting?.probs}/><div className="prob-legend">{Object.entries(p.scouting?.probs||{}).map(([r,v])=><span key={r}>{r} {v}%</span>)}</div><p className="explain">True rarity, professional career length and development path remain sealed until this player is drafted.</p></Panel><Panel title="College profile" eyebrow="VISIBLE"><div className="profile-grid"><Metric label="Class" value={cls(p.collegeYear)}/><Metric label="Age" value={p.age}/><Metric label="Position" value={p.position}/><Metric label="School" value={team?.name}/></div></Panel></div>}{tab==='Overview'&&!hidden&&<div className="two-col"><Panel title="God View" eyebrow="TRUE CAREER INFORMATION"><div className="truth-card static"><RarityPill rarity={p.trueRarity}/><div><span>CAREER ARC</span><h3>{p.developmentPath}</h3><p>{p.careerYears} scripted pro seasons · peak OVR {p.peakOverall}</p></div></div><div className="profile-grid"><Metric label="Pro year" value={p.proYear||0}/><Metric label="Draft" value={p.drafted?`R${p.draftRound} · #${p.draftPick}`:'Undrafted'}/><Metric label="Titles" value={p.championships||0}/><Metric label="Awards" value={p.awards.length}/></div></Panel><Panel title="Current home" eyebrow="TEAM"><button className="entity-team-link" onClick={()=>team&&openTeam(team.id)}><TeamMark team={team} size={54}/><span><b>{team?.name||'Free Agent'}</b><small>{p.contract?`${p.contract.years} yrs · ${money(p.contract.annual)}`:'No active contract'}</small></span></button>{college&&<div className="college-link">College: <b>{college.name}</b></div>}</Panel></div>}{tab==='Current Season'&&<Panel title="Current season" eyebrow={`YEAR ${u.year}`}><div className="summary-metrics"><Metric label="Games" value={p.currentSeason?.games||0}/><Metric label="Passing yards" value={num(p.currentSeason?.passYards||0)}/><Metric label="Rushing yards" value={num(p.currentSeason?.rushYards||0)}/><Metric label="Receiving yards" value={num(p.currentSeason?.recYards||0)}/><Metric label="Total TD" value={(p.currentSeason?.passTD||0)+(p.currentSeason?.rushTD||0)+(p.currentSeason?.recTD||0)}/><Metric label="Sacks" value={p.currentSeason?.sacks||0}/></div></Panel>}{tab==='Career'&&<Panel title="Season-by-season career" eyebrow="PERMANENT STATS"><table><thead><tr><th>Year</th><th>League</th><th>Team</th><th>Games</th><th>Pass</th><th>Rush</th><th>Rec</th><th>TD</th><th>Sacks</th><th>Finish / Titles</th></tr></thead><tbody>{[...p.stats.seasons].reverse().map(s=>{const t=findTeam(u,s.teamId),th=t?.history?.seasons?.find(x=>x.year===s.year);return <tr key={`${s.year}-${s.teamId}`}><td>Y{s.year}</td><td>{s.league}</td><td>{t?.name||s.teamId}</td><td>{s.games||0}</td><td>{num(s.passYards||0)}</td><td>{num(s.rushYards||0)}</td><td>{num(s.recYards||0)}</td><td>{(s.passTD||0)+(s.rushTD||0)+(s.recTD||0)}</td><td>{s.sacks||0}</td><td>{p.teamTitles?.find(x=>x.year===s.year)?.title||th?.finish||'—'}</td></tr>})}{!p.stats.seasons.length&&<tr><td colSpan="10"><Empty>No completed seasons yet.</Empty></td></tr>}</tbody></table></Panel>}{tab==='History'&&<div className="two-col"><Panel title="Awards & titles" eyebrow="ACHIEVEMENTS"><div className="award-list">{[...p.awards].reverse().map((a,i)=><span key={i}><b>{a.name}</b> · Year {a.year}</span>)}{[...(p.teamTitles||[])].reverse().map((a,i)=><span key={`t${i}`}><b>{a.title}</b> · Year {a.year} · {findTeam(u,a.teamId)?.name}</span>)}{!p.awards.length&&!p.teamTitles?.length&&<Empty>No major honors yet.</Empty>}</div></Panel><Panel title="Career movement" eyebrow="TRANSACTIONS · COLLEGE"><div className="award-list">{p.drafted&&<span><b>Drafted</b> · Year {p.draftYear} · Round {p.draftRound}, Pick {p.draftPick}</span>}{p.collegeHistory?.map((h,i)=><span key={`c${i}`}><b>College transfer</b> · {findTeam(u,h.fromId)?.name} → {findTeam(u,h.toId)?.name}</span>)}{txs.map((x,i)=><span key={`x${i}`}><b>{x.type}</b> · Year {x.year} · {findTeam(u,x.fromId)?.name||'Market'} → {findTeam(u,x.toId)?.name||'—'}</span>)}</div></Panel></div>}</div></div>}

export default function App(){
  const[u,setU]=useState(()=>{const raw=localStorage.getItem('afwc-autosave');if(raw){try{return ensureUniverse(JSON.parse(raw))}catch{}}return createUniverse('Gridiron-1')});const[nav,setNav]=useState('Home'),[entity,setEntity]=useState(null),[simulating,setSimulating]=useState(false);
  useEffect(()=>{localStorage.setItem('afwc-autosave',JSON.stringify(u));},[u]);
  const run=mode=>{setSimulating(true);requestAnimationFrame(()=>setTimeout(()=>{try{setU(prev=>mode==='week'?simulateWeeks(prev,1):mode==='four'?simulateWeeks(prev,4):mode==='end'?simulateToSeasonEnd(prev):mode==='offseason'?beginOffseason(prev):mode==='stage'?advanceOffseasonStage(prev):mode==='next'?startNextSeason(prev):prev);if(['end','offseason'].includes(mode))setNav(mode==='offseason'?'Offseason':'Home');}finally{setSimulating(false)}},20));};
  const openTeam=id=>id&&setEntity({type:'team',id});const openPlayer=id=>id&&setEntity({type:'player',id});const go=n=>{setEntity(null);setNav(n)};
  const common={u,openTeam,openPlayer};
  return <div className="app"><Header u={u} run={run} simulating={simulating}/><nav className="main-nav">{NAV.map(n=><button className={!entity&&nav===n?'active':''} onClick={()=>go(n)} key={n}>{n}</button>)}</nav><main>{entity?.type==='team'?<TeamPage u={u} id={entity.id} onBack={()=>setEntity(null)} openPlayer={openPlayer} openTeam={openTeam}/>:entity?.type==='player'?<PlayerPage u={u} id={entity.id} onBack={()=>setEntity(null)} openTeam={openTeam}/>:<>{nav==='Home'&&<Home {...common} run={run}/>} {nav==='NFL'&&<LeaguePage {...common} league="NFL"/>} {nav==='College'&&<LeaguePage {...common} league="COLLEGE"/>} {nav==='UFL'&&<LeaguePage {...common} league="UFL"/>} {nav==='Players'&&<PlayersPage u={u} openPlayer={openPlayer}/>} {nav==='Stats'&&<StatsPage u={u} openPlayer={openPlayer}/>} {nav==='Coaches'&&<CoachesPage u={u}/>} {nav==='Market'&&<Market {...common}/>} {nav==='Draft'&&<Draft u={u} openPlayer={openPlayer}/>} {nav==='Offseason'&&<Offseason {...common} run={run}/>} {nav==='ESPN'&&<ESPN {...common}/>} {nav==='Records'&&<Records {...common}/>} {nav==='Universe'&&<Universe u={u} setU={setU}/>}</>}</main>{simulating&&<div className="sim-overlay"><div className="sim-loader"><span/><b>ADVANCING THE UNIVERSE</b><small>{u.phase==='Offseason'?OFFSEASON_STAGES[u.offseasonState?.stageIndex||0]:`Year ${u.year} · ${u.phase}`}</small></div></div>}</div>
}
